            world.getServer().runCommand("fill 88 63 -200 118 64 -170 minecraft:stone");world.getServer().runCommand("fill 88 65 -200 118 101 -170 minecraft:air");world.getServer().runCommand("fill 88 100 -200 118 101 -170 minecraft:stone");world.getServer().runCommand("fill 103 65 -185 103 80 -185 minecraft:stone");world.getServer().runCommand("setblock 103 94 -185 minecraft:smooth_stone_slab[type=double]");world.getServer().runCommand("setblock 103 95 -185 minecraft:smooth_stone_slab[type=bottom]");world.getServer().runCommand("setblock 95 100 -185 minecraft:gold_block");world.getServer().runCommand("setblock 102 100 -185 minecraft:gold_block");world.getServer().runCommand("tp @a 103.5 65 -181 180 0");world.getServer().runCommand("gamemode adventure @a");world.getServer().runOnServer(MapAdventureGameTest::capturedF7Sidebar);context.waitTicks(8);
