    private static java.nio.file.Path fixture(String json){try{var folder=java.nio.file.Path.of("fme-import-fixture");java.nio.file.Files.createDirectories(folder);var path=folder.resolve("extrasConfig.json");java.nio.file.Files.writeString(path,json);return path;}catch(Exception error){throw new AssertionError(error);}}
    private static String readConfig(){try{return java.nio.file.Files.readString(com.customcosmetics.config.CosmeticsConfigDir.getCosmeticsConfigDir().resolve("map-editor.json"));}catch(Exception error){throw new AssertionError(error);}}
    private static String cores(){try{var method=DungeonRooms.class.getDeclaredMethod("core",int.class,int.class);method.setAccessible(true);return method.invoke(null,-121,-185)+" / "+method.invoke(null,-121,-186);}catch(Exception error){return error.toString();}}
    private static net.minecraft.client.input.MouseButtonEvent event(int x,int y,String name){try{var info=new net.minecraft.client.input.MouseButtonInfo(button(name),0);return new net.minecraft.client.input.MouseButtonEvent(x,y,info);}catch(Exception error){throw new AssertionError(error);}}
    private static int button(String name){try{return com.mojang.blaze3d.platform.InputConstants.class.getField(name).getInt(null);}catch(Exception error){throw new AssertionError(error);}}
    private static void mouse(ClientGameTestContext context,String name){context.getInput().holdMouseFor(button(name),1);context.waitTicks(4);}
    private static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
